package org.circus.core;

import java.io.*;
import java.nio.file.*;
import java.util.*;

/** Actual readonly41ABF0 file boundary with canonical raw tables. Original
 *game EXE/VM/window are not executed; copied/truncated fixtures stay in build. */
public final class Pc1CatalogFilesAudit {
    private static int count;
    private static void check(boolean value,String why){count++;if(!value)throw new AssertionError(why);}
    private static void root(Pc1PathGlobals paths,Pc1WindowsPaths windows,Path value)throws IOException{byte[] raw=windows.encode(value.toString());for(int address:new int[]{Pc1NativePaths.PRIMARY_ROOT,Pc1NativePaths.FALLBACK_ROOT}){for(int n=0;n<raw.length;n++)paths.write(address+n,raw[n]);paths.write(address+raw.length,0);}}
    private static byte[] save(Pc1CatalogMemory memory)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();memory.save(new DataOutputStream(out));return out.toByteArray();}
    private static byte[] prefix(byte[] raw){int n=0;while(n<raw.length&&raw[n]!=0)n++;return Arrays.copyOf(raw,n);}
    public static void main(String[] args)throws Exception{
        if(args.length!=4)throw new IOException("Require paths.dll image_io.dll explicit_GAME_ROOT owned_FIXTURE_ROOT");Path game=Paths.get(args[2]).toAbsolutePath().normalize(),fixture=Paths.get(args[3]).toAbsolutePath().normalize();if(fixture.startsWith(game))throw new IOException("Catalog audit fixture must be outside original game directory");Path namesFile=game.resolve("AdvData/DAT/names.dat");byte[] actual=Files.readAllBytes(namesFile);String originalHash=Binary.sha256(actual);NamesCatalog independent=new NamesCatalog(actual,true);byte[] settings=new byte[Pc1NativeSettings.SIZE];Pc1NativeMemory bus=new Pc1NativeMemory(Pc1NativeFrame.zeroBss(),Pc1CodeBuffer.zeroBss(),new Pc1NativeMemory.SettingsBytes(){public int read(int at){return settings[at]&255;}public void write(int at,int value){settings[at]=(byte)value;}});Pc1PathGlobals paths=new Pc1PathGlobals(bus);Pc1CatalogMemory memory=new Pc1CatalogMemory(bus);Pc1WindowsPaths windows=new Pc1WindowsPaths(Paths.get(args[0]));root(paths,windows,game);
        try(Pc1WindowsImageIo io=new Pc1WindowsImageIo(Paths.get(args[1]))){Pc1CatalogLoader loader=new Pc1CatalogLoader(memory,new Pc1CatalogFiles(memory,windows,io));Pc1CatalogLoader.LocalDword local=Pc1CatalogLoader.LocalDword.unknown();check(loader.load(local)==0&&Arrays.equals(local.knownBytes(),new byte[]{6,0,0,0}),"actual four-byte CRT read establishes known stack count6");check(io.openCount()==0&&!memory.active(),"native file closes after complete synchronous startup");Pc1CatalogMemory.Table[] tables=Pc1CatalogMemory.Table.values();String[] categories={"system_scripts","music","sound","images","scenario_scripts"};
            for(int t=0;t<tables.length;t++){List<NamesCatalog.Entry> rows=independent.table(categories[t]);check(memory.count(tables[t])==rows.size(),"actual native count "+categories[t]);for(NamesCatalog.Entry row:rows){check(Arrays.equals(memory.name(tables[t],row.index),row.nameBytes),"all raw names match actual NAMES row "+categories[t]+":"+row.index);if(tables[t]==Pc1CatalogMemory.Table.MUSIC||tables[t]==Pc1CatalogMemory.Table.SCENARIO)check(Arrays.equals(memory.label(tables[t],row.index),prefix(row.extra)),"actual label bytes "+categories[t]+":"+row.index);}}
            Pc1Audio.Catalog audio=memory.audioCatalog();for(NamesCatalog.Entry row:independent.table("music"))check(audio.music(row.index).gainTrim==(int)Binary.u32(row.extra,60),"actual native music188 metadata");for(NamesCatalog.Entry row:independent.table("sound"))check(audio.sound(row.index).gainTrim==(int)Binary.u32(row.extra,0),"actual native SE128 metadata");
            int cg=independent.table("images").size();Pc1CgVisit.visit(independent.table("images").get(cg-1).nameBytes,memory.cgCatalog(),(index,value)->bus.writeAddress(Pc1CgVisit.CG+index,value));check(settings[Pc1NativeSettings.CG_OFFSET+cg-1]==1,"CG adapter marks the same canonical live system.dat byte");byte[] snapshot=save(memory);Path fixtureFile=fixture.resolve("AdvData/DAT/names.dat");Files.createDirectories(fixtureFile.getParent());root(paths,windows,fixture);
            Files.write(fixtureFile,new byte[]{6,0});Pc1CatalogLoader.LocalDword unknown=Pc1CatalogLoader.LocalDword.unknown();boolean gated=false;try{loader.load(unknown);}catch(IOException exact){gated=exact.getMessage().contains("unknown native stack DWORD suffix");}check(gated&&Arrays.equals(unknown.knownBytes(),new byte[]{6,0})&&Arrays.equals(snapshot,save(memory))&&io.openCount()==0,"real short-read gates unknown stack suffix without inventing zeros or clearing tables");
            check(loader.load(Pc1CatalogLoader.LocalDword.knownPrefix(new byte[]{6,0,0,0}))==0&&Arrays.equals(snapshot,save(memory)),"explicitly known old local/counts make EOF short-read succeed with every stale table byte preserved");Files.write(fixtureFile,new byte[]{5,0,0,0});check(loader.load(Pc1CatalogLoader.LocalDword.unknown())==-1&&Arrays.equals(snapshot,save(memory)),"real bad first count closes before any table overwrite");byte[] trailing=Arrays.copyOf(actual,actual.length+3);trailing[actual.length]=91;trailing[actual.length+1]=92;trailing[actual.length+2]=93;Files.write(fixtureFile,trailing);check(loader.load(Pc1CatalogLoader.LocalDword.unknown())==0&&Arrays.equals(snapshot,save(memory)),"native loader ignores real trailing file bytes");check(!Files.exists(fixture.resolve("system.dat")),"catalog load/CG visit never silently persists system.dat");
            // A drive-qualified name bypasses even an unterminated extension.
            //D:. is this process's D-drive current directory, not a game file.
            for(int n=0;n<8;n++)memory.write(Pc1CatalogMemory.EXTENSION+n,'E');byte[] directory={'D',':','.',0};for(int n=0;n<directory.length;n++)memory.write(Pc1CatalogMemory.NAME+n,directory[n]);check(loader.load(Pc1CatalogLoader.LocalDword.unknown())==-1,"actual drive-qualified readonly directory open bypasses bad extension rather than eagerly reading it or guessing NAMES");memory.restore(Pc1CatalogMemory.loadImage(new DataInputStream(new ByteArrayInputStream(snapshot))));check(Arrays.equals(snapshot,save(memory)),"raw path literals restore through same canonical owner");
            System.out.println("actualCounts=system6,music"+audio.musicCount()+",sound"+audio.soundCount()+",CG"+memory.count(Pc1CatalogMemory.Table.CG)+",scenario"+memory.count(Pc1CatalogMemory.Table.SCENARIO));System.out.println("rawCatalogSha256="+Binary.sha256(snapshot)+";namesFileSha256="+originalHash+";ACP="+windows.ansiCodePage());
        }
        check(Binary.sha256(Files.readAllBytes(namesFile)).equals(originalHash),"original NAMES remains byte-exact readonly");System.out.println("Pc1CatalogFilesAudit PASS "+count+"; actual WindowsA/CRT and original NAMES; explicit owned short-read fixtures; no original EXE/VM or original writes");
    }
}
